import uuid

class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        self._jobs = {}  # job_id -> {state, worker, token, expiry}
        self._order = []  # insertion order

    def add(self, job_id):
        with self._lock:
            if job_id in self._jobs:
                return
            self._jobs[job_id] = {"state": "queued", "worker": None, "token": None, "expiry": None}
            self._order.append(job_id)

    def claim(self, worker, now, ttl):
        if ttl <= 0:
            return None
        with self._lock:
            for jid in self._order:
                rec = self._jobs[jid]
                if rec["state"] == "queued":
                    token = uuid.uuid4().hex
                    rec.update({"state": "running", "worker": worker, "token": token, "expiry": now + ttl})
                    lease = {"job_id": jid, "worker": worker, "token": token}
                    return lease
                if rec["state"] == "running" and rec["expiry"] is not None and rec["expiry"] <= now:
                    token = uuid.uuid4().hex
                    rec.update({"worker": worker, "token": token, "expiry": now + ttl})
                    lease = {"job_id": jid, "worker": worker, "token": token}
                    return lease
            return None

    def renew(self, lease, now, ttl):
        if ttl <= 0 or lease is None:
            return False
        with self._lock:
            jid = lease.get("job_id")
            if jid not in self._jobs:
                return False
            rec = self._jobs[jid]
            if rec["state"] != "running" or rec["token"] != lease.get("token") or rec["worker"] != lease.get("worker"):
                return False
            if rec["expiry"] is None or rec["expiry"] <= now:
                return False
            rec["expiry"] = now + ttl
            return True

    def complete(self, lease, now):
        if lease is None:
            return False
        with self._lock:
            jid = lease.get("job_id")
            if jid not in self._jobs:
                return False
            rec = self._jobs[jid]
            if rec["state"] != "running" or rec["token"] != lease.get("token") or rec["worker"] != lease.get("worker"):
                return False
            if rec["expiry"] is None or rec["expiry"] <= now:
                return False
            # remove job
            del self._jobs[jid]
            self._order.remove(jid)
